var gamepad = null;
/**
* An array with 16 entries. For each entry _e_:
*
* *   if _e_ <= 0, then _-e_ is 0 | 1 | 2 and represents a joystick button;
* *   if _e_ > 0, then _e_ is a key on the keyboard that is pressed;
* *   if _e_ is undefined, nothing happens.
*/
var gamepadMap = [];
/**
* An array with 16 entries saying whether or not the given button is
* currently pressed.
*/
var gamepadState = [];
var flipX = false;
var flipY = false;
if (typeof window !== "undefined") window.addEventListener("gamepadconnected", function(e) {
	gamepad = e.gamepad;
});
function processGamepad(io) {
	if (typeof navigator === "undefined" || typeof navigator.getGamepads !== "function") return;
	gamepad = navigator.getGamepads()[0];
	if (!gamepad) return;
	const x = (gamepad.axes[0] * 1.414 + 1) / 2;
	const y = (gamepad.axes[1] * 1.414 + 1) / 2;
	io.paddle(0, flipX ? 1 - x : x);
	io.paddle(1, flipY ? 1 - y : y);
	for (let idx = 0; idx < gamepad.buttons.length; idx++) {
		const val = gamepadMap[idx];
		if (val !== void 0) {
			const old = gamepadState[idx];
			const button = gamepad.buttons[idx];
			let pressed;
			if (typeof button === "object") pressed = button.pressed;
			else pressed = button === 1;
			if (pressed && !old) {
				if (val <= 0) io.buttonDown(-val);
				else io.keyDown(val);
			} else if (!pressed && old) {
				if (val <= 0) io.buttonUp(-val);
				else io.keyUp();
			}
			gamepadState[idx] = pressed;
		}
	}
}
var Apple2 = class {
	paused = false;
	theDebugger;
	runTimer = null;
	runAnimationFrame = null;
	cpu;
	gr;
	gr2;
	hgr;
	hgr2;
	vm;
	io;
	mmu;
	ram;
	characterRom;
	rom;
	tick;
	stats = {
		cycles: 0,
		frames: 0,
		renderedFrames: 0
	};
	ready;
	constructor(options) {
		this.ready = this.init(options);
	}
	async init(options) {
		const LoresPage = LoresPage2D;
		const HiresPage = HiresPage2D;
		const VideoModes = VideoModes2D;
		this.cpu = new CPU6502({ flavor: options.enhanced ? FLAVOR_ROCKWELL_65C02 : FLAVOR_6502 });
		this.vm = new VideoModes(options.canvas, options.e);
		await this.vm.ready;
		this.rom = new Apple2eEnhancedROM();
		this.characterRom = apple2enh_charset;
		this.ram = [new RAM(0, 191)];
		if (options.e) this.ram.push(new RAM(0, 191));
		this.gr = new LoresPage(this.vm, 1, this.ram, this.characterRom, options.e);
		this.gr2 = new LoresPage(this.vm, 2, this.ram, this.characterRom, options.e);
		this.hgr = new HiresPage(this.vm, 1, this.ram);
		this.hgr2 = new HiresPage(this.vm, 2, this.ram);
		this.io = new Apple2IO(this.cpu, this.vm);
		this.tick = options.tick;
		if (options.e) {
			this.mmu = new MMU(this.cpu, this.vm, this.gr, this.gr2, this.hgr, this.hgr2, this.io, this.ram, this.rom);
			this.cpu.addPageHandler(this.mmu);
		} else {
			this.cpu.addPageHandler(this.ram[0]);
			this.cpu.addPageHandler(this.gr);
			this.cpu.addPageHandler(this.gr2);
			this.cpu.addPageHandler(this.hgr);
			this.cpu.addPageHandler(this.hgr2);
			this.cpu.addPageHandler(this.io);
			this.cpu.addPageHandler(this.rom);
		}
	}
	/**
	* Runs the emulator. If the emulator is already running, this does
	* nothing. When this function exits either `runTimer` or
	* `runAnimationFrame` will be non-null.
	*/
	run() {
		this.paused = false;
		if (this.runTimer || this.runAnimationFrame) return;
		this.theDebugger = new Debugger(this.cpu, this);
		this.theDebugger.addSymbols(SYMBOLS);
		const interval = 30;
		let now, last = Date.now();
		const runFn = () => {
			const kHz = this.io.getKHz();
			now = Date.now();
			const stepMax = kHz * interval;
			let step = (now - last) * kHz;
			last = now;
			if (step > stepMax) step = stepMax;
			if (this.theDebugger) this.theDebugger.stepCycles(step);
			else this.cpu.stepCycles(step);
			if (this.mmu) this.mmu.resetVB();
			if (this.io.annunciator(0)) {
				const imageData = this.io.blit();
				if (imageData) {
					this.vm.blit(imageData);
					this.stats.renderedFrames++;
				}
			} else if (this.vm.blit()) this.stats.renderedFrames++;
			this.stats.cycles = this.cpu.getCycles();
			this.stats.frames++;
			this.io.tick();
			this.tick();
			processGamepad(this.io);
			if (!this.paused && requestAnimationFrame) this.runAnimationFrame = requestAnimationFrame(runFn);
		};
		if (requestAnimationFrame) this.runAnimationFrame = requestAnimationFrame(runFn);
		else this.runTimer = window.setInterval(runFn, interval);
	}
	stop() {
		this.paused = true;
		if (this.runTimer) clearInterval(this.runTimer);
		if (this.runAnimationFrame) cancelAnimationFrame(this.runAnimationFrame);
		this.runTimer = null;
		this.runAnimationFrame = null;
	}
	isRunning() {
		return !this.paused;
	}
	getState() {
		return {
			cpu: this.cpu.getState(),
			vm: this.vm.getState(),
			io: this.io.getState(),
			mmu: this.mmu?.getState(),
			ram: this.ram?.map((bank) => bank.getState())
		};
	}
	setState(state) {
		this.cpu.setState(state.cpu);
		this.vm.setState(state.vm);
		this.io.setState(state.io);
		if (this.mmu && state.mmu) this.mmu.setState(state.mmu);
		if (this.ram) this.ram.forEach((bank, idx) => {
			if (state.ram) bank.setState(state.ram[idx]);
		});
	}
	reset() {
		this.cpu.reset();
	}
	getStats() {
		return this.stats;
	}
	getCPU() {
		return this.cpu;
	}
	getIO() {
		return this.io;
	}
	getMMU() {
		return this.mmu;
	}
	getROM() {
		return this.rom;
	}
	getVideoModes() {
		return this.vm;
	}
};
